{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "PEMA, a small polar diamide, had at least 80% absolute oral bioavailability in normal subjects, directly supporting high F for a polar amide-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Odanacatib, which shares a sulfone and amide motif with the query, had 30% absolute bioavailability at 50 mg fasted in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, a basic amine/amide antiarrhythmic, had 32 ± 7% absolute oral bioavailability in normal subjects, supporting high F despite a basic nitrogen.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pentopril showed 50–70% oral bioavailability in healthy subjects, supporting high F for an amide/carboxylate-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin had 57.8% absolute oral bioavailability in healthy subjects, supporting high F for a heteroaromatic amide with basic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Vilazodone had 72% absolute bioavailability in humans with food, supporting high F for a piperazine-containing indole amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Trazodone had 91% absolute bioavailability in fasted men, supporting high F for a piperazine/triazolone drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Carbamazepine epoxide had at least 78% oral bioavailability, supporting high F for a tricyclic carboxamide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Flupentixol had 55% mean systemic availability after oral administration, supporting high F for a tricyclic thioxanthene with a basic side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Benazeprilat had 27.1–28.5% absolute bioavailability from oral benazepril, supporting F above 20% for an amide/carboxylate drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human analogues report absolute oral bioavailability at or above 20%, mostly 30–90%, including molecules with sulfone, amide, basic amine, and tricyclic features; therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability data are available for the query molecule itself.",
    "Dose- and food-dependent absorption, as seen with odanacatib, was not directly assessed for the query.",
    "Human first-pass metabolism and transporter effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

